// Clean-room TSVC s235 profile; see package rights note.
fn put64(out &u8,p int,v i64){mut b:=u64(v);for k in 0..8{unsafe{out[p+k]=u8(b&255)};b>>=8}}
@[export:'tsvc_s235_fused_vector_matrix_recurrence']
pub fn tsvc_s235_fused_vector_matrix_recurrence(input &i64,length usize,output &u8,capacity usize)i64{if unsafe{input==nil}||length<15||length>153{return -1};nr:=unsafe{input[0]};if nr<2||nr>8{return -1};n:=int(nr);nn:=n*n;if int(length)!=1+3*n+2*nn{return -1};mut a:=[8]i64{};mut b:=[8]i64{};mut c:=[8]i64{};mut aa:=[64]i64{};mut bb:=[64]i64{};mut p:=1;for i in 0..n{x:=unsafe{input[p]};p++;if x< -1||x>1{return -1};a[i]=x};for i in 0..n{x:=unsafe{input[p]};p++;if x< -1||x>1{return -1};b[i]=x};for i in 0..n{x:=unsafe{input[p]};p++;if x< -1||x>1{return -1};c[i]=x};for i in 0..nn{x:=unsafe{input[p]};p++;if x< -1||x>1{return -1};aa[i]=x};for i in 0..nn{x:=unsafe{input[p]};p++;if x< -1||x>1{return -1};bb[i]=x};if unsafe{output==nil}||capacity<usize(8*(n+nn)){return -2};for col in 0..n{a[col]+=b[col]*c[col];for row in 1..n{k:=row*n+col;aa[k]=aa[k-n]+bb[k]*a[col]}};for i in 0..n{put64(output,8*i,a[i])};for i in 0..nn{put64(output,8*(n+i),aa[i])};return i64(n+nn)}
